package com.quincaisoft.documents.application;
import com.quincaisoft.documents.api.DocumentService;import com.quincaisoft.documents.infrastructure.*;import com.quincaisoft.shared.*;
import jakarta.persistence.*;import org.springframework.stereotype.Service;import tools.jackson.databind.json.JsonMapper;
import java.util.*;import java.time.*;import java.nio.charset.StandardCharsets;import java.security.*;
@Service public class DefaultDocumentService implements DocumentService {
 private final EntityManager em;private final ScopedTransactions tx;private final JsonMapper json;
 public DefaultDocumentService(EntityManager em,ScopedTransactions tx,JsonMapper json){this.em=em;this.tx=tx;this.json=json;}
 private DocumentSettings config(){var s=TenantContext.current();var r=em.find(DocumentSettings.class,new DocumentSettings.Key(s.tenantId(),s.companyId(),s.branchId()),LockModeType.PESSIMISTIC_READ);if(r==null)throw new IllegalStateException("Configure issuer identity and document series before posting");return r;}
 private Settings view(DocumentSettings r){return new Settings(r.issuerName,r.issuerAddress,r.registrationNumber,r.fiscalSeries,r.locale,r.version);}
 public Settings settings(){return tx.execute(()->{var s=TenantContext.current();var r=em.find(DocumentSettings.class,new DocumentSettings.Key(s.tenantId(),s.companyId(),s.branchId()));return r==null?new Settings("","","","","en",0):view(r);});}
 /** HTTP settings commands retain their original response even after later settings revisions. */
 public Settings configure(UUID operationId,Settings input){
  if(operationId==null||input==null)throw new IllegalArgumentException("Operation ID and settings required");
  String requestHash=sha("DOCUMENT_SETTINGS_CONFIGURE_V1\n"+json.writeValueAsString(input));
  return tx.execute(()->{
   var scope=TenantContext.current();
   em.createNativeQuery("select 1 from pg_advisory_xact_lock(hashtextextended(:key,0))")
     .setParameter("key",scope.tenantId()+":"+operationId).getSingleResult();
   var rows=em.createNativeQuery("select request_hash,response_json::text,company_id,branch_id,actor_id,source_type from idempotency_result where tenant_id=:tenant and operation_id=:operation")
     .setParameter("tenant",scope.tenantId()).setParameter("operation",operationId).getResultList();
   if(!rows.isEmpty()){
    Object[] row=(Object[])rows.getFirst();
    if(!requestHash.equals(row[0])||!scope.companyId().equals(row[2])||!scope.branchId().equals(row[3])||!scope.actorId().equals(row[4])||!"DOCUMENT_SETTINGS".equals(row[5]))
     throw new IllegalStateException("Operation ID belongs to another request, scope or actor");
    if(row[1]==null)throw new IllegalStateException("Original receipt expired; reconcile this operation before changing settings");
    return json.readValue((String)row[1],Settings.class);
   }
   Settings result=configure(input);
   em.createNativeQuery("insert into idempotency_result(tenant_id,operation_id,company_id,branch_id,request_hash,source_type,source_id,response_json) values(:tenant,:operation,:company,:branch,:hash,'DOCUMENT_SETTINGS',:source,cast(:response as jsonb))")
     .setParameter("tenant",scope.tenantId()).setParameter("operation",operationId)
     .setParameter("company",scope.companyId()).setParameter("branch",scope.branchId())
     .setParameter("hash",requestHash).setParameter("source",scope.branchId())
     .setParameter("response",json.writeValueAsString(result)).executeUpdate();
   return result;
  });
 }
 public Settings configure(Settings input){if(input==null||input.issuerName()==null||input.issuerName().isBlank()||input.issuerAddress()==null||input.issuerAddress().isBlank()||input.registrationNumber()==null||input.registrationNumber().isBlank()||input.fiscalSeries()==null||!input.fiscalSeries().matches("[A-Z0-9-]{1,24}")||input.locale()==null||!Set.of("en","fr").contains(input.locale()))throw new IllegalArgumentException("Issuer identity, series and EN/FR locale required");
 return tx.execute(()->{var s=TenantContext.current();em.createNativeQuery("select 1 from pg_advisory_xact_lock(hashtextextended(:k,0))").setParameter("k","document-settings:"+s.tenantId()+s.branchId()).getSingleResult();var r=em.find(DocumentSettings.class,new DocumentSettings.Key(s.tenantId(),s.companyId(),s.branchId()),LockModeType.PESSIMISTIC_WRITE);boolean fresh=r==null;if(fresh){if(input.version()!=0)throw new RevisionConflict("Settings changed");r=new DocumentSettings();r.tenantId=s.tenantId();r.companyId=s.companyId();r.branchId=s.branchId();}else if(r.version!=input.version())throw new RevisionConflict("Settings changed");r.issuerName=input.issuerName();r.issuerAddress=input.issuerAddress();r.registrationNumber=input.registrationNumber();r.fiscalSeries=input.fiscalSeries();r.locale=input.locale();r.version=Math.incrementExact(r.version);if(fresh)em.persist(r);em.flush();return view(r);});}
 public Snapshot issue(Issue request){if(request==null||request.sourceId()==null||request.operationId()==null||request.businessDate()==null||request.items()==null||request.items().isEmpty()||!Set.of("INVOICE","CREDIT_NOTE","QUOTATION").contains(request.kind()))throw new IllegalArgumentException("Complete document source required");
 if("CREDIT_NOTE".equals(request.kind())&&request.originalSourceId()==null)throw new IllegalArgumentException("Credit note must reference original sale");long itemTotal=0;for(var item:request.items()){if(item.productId()==null||item.description()==null||item.baseUnit()==null||item.quantityMilli()==null||!item.quantityMilli().matches("[1-9][0-9]*")||item.totalXaf()==null||!item.totalXaf().matches("[0-9]+"))throw new IllegalArgumentException("Invalid document line");Long.parseLong(item.quantityMilli());itemTotal=Math.addExact(itemTotal,Long.parseLong(item.totalXaf()));}if(!Long.toString(itemTotal).equals(request.totalXaf())||itemTotal<=0)throw new IllegalArgumentException("Document lines must reconcile exactly to total");
 return tx.execute(()->{var s=TenantContext.current();var existing=em.createQuery("select d from DocumentSnapshot d where d.sourceId=:id and d.kind=:kind",DocumentSnapshot.class).setParameter("id",request.sourceId()).setParameter("kind",request.kind()).getResultList();if(!existing.isEmpty()){var d=existing.getFirst();if(!d.operationId.equals(request.operationId())||!json.readValue(json.writeValueAsString(json.readTree(d.content).get("source")),Issue.class).equals(request))throw new IllegalStateException("Source document already issued with different content");return view(d);}
 var cfg=config();String series=cfg.fiscalSeries+"-"+request.businessDate().getYear();String key=s.tenantId()+":"+s.branchId()+":"+request.kind()+":"+series;em.createNativeQuery("select 1 from pg_advisory_xact_lock(hashtextextended(:k,0))").setParameter("k",key).getSingleResult();
 var counter=em.find(DocumentSeries.class,new DocumentSeries.Key(s.tenantId(),s.companyId(),s.branchId(),request.kind(),series),LockModeType.PESSIMISTIC_WRITE);if(counter==null){counter=new DocumentSeries();counter.tenantId=s.tenantId();counter.companyId=s.companyId();counter.branchId=s.branchId();counter.kind=request.kind();counter.fiscalSeries=series;counter.nextNumber=1;em.persist(counter);}long number=counter.nextNumber;counter.nextNumber=Math.incrementExact(number);
 var d=new DocumentSnapshot();d.tenantId=s.tenantId();d.companyId=s.companyId();d.branchId=s.branchId();d.id=UUID.randomUUID();d.sourceId=request.sourceId();d.operationId=request.operationId();d.kind=request.kind();d.number=request.kind()+"-"+series+"-"+String.format(java.util.Locale.ROOT,"%08d",number);d.businessDate=request.businessDate();d.totalXaf=Long.parseLong(request.totalXaf());if(d.totalXaf<=0)throw new IllegalArgumentException("Positive integral XAF document required");d.issuedAt=Instant.now();
 var data=new LinkedHashMap<String,Object>();data.put("number",d.number);data.put("actorId",s.actorId().toString());data.put("tenantId",s.tenantId().toString());data.put("companyId",s.companyId().toString());data.put("branchId",s.branchId().toString());data.put("issuer",view(cfg));data.put("source",request);data.put("templateVersion","A4-1");data.put("issuedAt",d.issuedAt.toString());d.content=json.writeValueAsString(data);d.sha256=sha(d.content);em.persist(d);em.flush();return view(d);});}
 private Snapshot view(DocumentSnapshot d){return new Snapshot(d.id,d.number,d.kind,d.sourceId,d.businessDate,Long.toString(d.totalXaf),d.sha256,d.content,d.issuedAt);}
 public Snapshot get(UUID id){return tx.execute(()->{var s=TenantContext.current();var d=em.find(DocumentSnapshot.class,new DocumentSnapshot.Key(s.tenantId(),s.companyId(),id));if(d==null)throw new NoSuchElementException("Document not found");return view(d);});}
 public List<Snapshot> list(UUID sourceId){return tx.execute(()->{var q=em.createQuery("select d from DocumentSnapshot d "+(sourceId==null?"":"where d.sourceId=:source ")+"order by d.issuedAt desc,d.id",DocumentSnapshot.class);if(sourceId!=null)q.setParameter("source",sourceId);return q.setMaxResults(100).getResultList().stream().map(this::view).toList();});}
 public String render(UUID id,boolean copy){var d=get(id);var data=json.readTree(d.content());var issuer=data.get("issuer");boolean fr="fr".equals(issuer.get("locale").asText());StringBuilder html=new StringBuilder("<!doctype html><html lang=\"").append(fr?"fr":"en").append("\"><meta charset=\"utf-8\"><title>").append(esc(d.number())).append("</title><style>body{font:14px sans-serif;max-width:800px;margin:40px auto;color:#142934}table{width:100%;border-collapse:collapse}td,th{padding:9px;border-bottom:1px solid #ddd;text-align:left}@media print{body{margin:0}}</style><h1>").append(esc(issuer.get("issuerName").asText())).append("</h1><p>").append(esc(issuer.get("issuerAddress").asText())).append("<br>").append(esc(issuer.get("registrationNumber").asText())).append("</p><h2>").append(esc(d.kind())).append(" ").append(esc(d.number())).append(copy?(fr?" — COPIE":" — COPY"):"").append("</h2><p>").append(d.businessDate()).append("</p><p>").append(data.get("source").get("originalSourceId").isNull()?"":("Original sale: "+esc(data.get("source").get("originalSourceId").asText()))).append("</p><table><tr><th>").append(fr?"Désignation":"Description").append("</th><th>").append(fr?"Quantité (milli-unités)":"Quantity (milli-units)").append("</th><th>XAF</th></tr>");for(var item:data.get("source").get("items"))html.append("<tr><td>").append(esc(item.get("description").asText())).append("</td><td>").append(esc(item.get("quantityMilli").asText())).append("</td><td>").append(esc(item.get("totalXaf").asText())).append("</td></tr>");return html.append("</table><h3>Total: ").append(d.totalXaf()).append(" XAF</h3><small>SHA-256: ").append(d.sha256()).append("</small></html>").toString();}
 static String esc(String v){return v.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}
 static String sha(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
